import numpy as np
from PIL import Image

# Create the directory structure
InputPath = 'data/images-after-converted_small/'
os.makedirs(InputPath, exist_ok=True)

# Create directories for different combinations
configs = [
    ('L', 'CC'),
    ('R', 'CC'),
    ('L', 'MLO'),
    ('R', 'MLO'),
]

for laterality, view in configs:
    dir_path = os.path.join(InputPath, f"{laterality}-{view}")
    os.makedirs(dir_path, exist_ok=True)

# Create sample images
import random
sample_data = {
    'L': {
        'CC': ['img_001', 'img_003', 'img_005'],
        'MLO': []
    },
    'R': {
        'CC': [],
        'MLO': ['img_002', 'img_004', 'img_006']
    }
}

for laterality, views in sample_data.items():
    for view, img_ids in views.items():
        dir_path = os.path.join(InputPath, f"{laterality}-{view}")
        for img_id in img_ids:
            img_path = os.path.join(dir_path, f"{img_id}.png")
            # Create a random 100x100 grayscale image
            img = np.random.randint(0, 256, (100, 100), dtype=np.uint8)
            pil_img = Image.fromarray(img)
            pil_img.save(img_path)
            print(f"Created: {img_path}")"}

